CREATE TABLE private.practice_project_owners (project_id uuid PRIMARY KEY REFERENCES public.projects(id) ON DELETE CASCADE, owner_id uuid NOT NULL);
REVOKE ALL ON private.practice_project_owners FROM PUBLIC, anon, authenticated;
CREATE OR REPLACE FUNCTION private.can_edit_practice_project(_project_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$ SELECT NOT EXISTS (SELECT 1 FROM private.practice_project_owners p WHERE p.project_id = _project_id AND p.owner_id IS DISTINCT FROM auth.uid()); $$;
REVOKE ALL ON FUNCTION private.can_edit_practice_project(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION private.can_edit_practice_project(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION private.register_practice_project() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ BEGIN IF NEW.name IN ('Demo: Pump Station Piping Upgrade', 'Practice: Fort McMurray Civil Earthworks') THEN INSERT INTO private.practice_project_owners(project_id, owner_id) VALUES (NEW.id, NEW.created_by) ON CONFLICT (project_id) DO NOTHING; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION private.register_practice_project() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER register_personal_practice_project AFTER INSERT ON public.projects FOR EACH ROW EXECUTE FUNCTION private.register_practice_project();
INSERT INTO private.practice_project_owners(project_id,owner_id) SELECT id,created_by FROM public.projects WHERE name IN ('Demo: Pump Station Piping Upgrade','Practice: Fort McMurray Civil Earthworks') ON CONFLICT DO NOTHING;
DO $$ DECLARE t record; c text; col text; BEGIN FOR t IN SELECT table_name FROM information_schema.columns WHERE table_schema='public' AND column_name='project_id' UNION SELECT 'projects' LOOP col := CASE WHEN t.table_name='projects' THEN 'id' ELSE 'project_id' END; FOREACH c IN ARRAY ARRAY['INSERT','UPDATE','DELETE'] LOOP EXECUTE format('CREATE POLICY %I ON public.%I AS RESTRICTIVE FOR %s TO authenticated %s', 'Personal practice owner '||lower(c), t.table_name,c, CASE WHEN c='INSERT' THEN format('WITH CHECK (private.can_edit_practice_project(%I))',col) WHEN c='DELETE' THEN format('USING (private.can_edit_practice_project(%I))',col) ELSE format('USING (private.can_edit_practice_project(%I)) WITH CHECK (private.can_edit_practice_project(%I))',col,col) END); END LOOP; END LOOP; END $$;